local ECSComponent = import("Frame.ECS.ECSComponent")

---@class NightCatQuestComponent
local NightCatQuestComponent = Class("NightCatQuestComponent", ECSComponent)
local DailyQuestDojo = import("Game.Dojo.DailyQuestDojo")
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local UIModule = CS.Engine.UI.UIModule

function NightCatQuestComponent:__init()
    self._activityUuId = 0                     --
    self._curActivityId = 0                     --当前活动id

    self._climbingResetTtl = 0               --爬塔倒计时
    self._curTowerQuestId = 0                --当前的爬塔id
    self._climbingResetNum = 0               --重置次数
    self._climbingMaxFloor = 0               --爬过的最大id
    self._climbingAssembleBuffIds = {}               --装备的道具 list
    self._climbingHaveBuffIds = {}              --已解锁的道具 key goodsId value level

    self._timeDown = nil
    self._redPointList = {}                  --buff小红点需要的数据

    self._isInit = false
end 

function NightCatQuestComponent:__delete()
    self._activityUuId = 0                     --
    self._curActivityId = 0                     --当前活动id
    self._climbingResetTtl = 0               --爬塔倒计时
    self._curTowerQuestId = 0                --当前的爬塔id
    self._climbingResetNum = 0               --重置次数
    self._climbingMaxFloor = 0               --爬过的最大id
    self._climbingAssembleBuffIds = {}               --装备的道具 key goodsId value level
    self._climbingHaveBuffIds = {}              --已解锁的道具 key goodsId value level
    self._timeDown = nil
    self._redPointList = {} 

    self._isInit = false
end

function NightCatQuestComponent:Initial(activityUuid, jsonData)
    if not jsonData then
        return
    end
    
    self._activityUuId = checkNumber(activityUuid)

    local activityConf = checkTable(jsonData.activityConf)
    self._curActivityId = checkNumber(activityConf.id)

    self._climbingResetTtl = checkNumber(jsonData.climbingResetTtl)
    local t = checkTable(jsonData.climbingInfo)
    self._curTowerQuestId = checkNumber(t.climbingNowFloor)
    self._climbingResetNum = checkNumber(t.climbingResetNum)
    self._climbingNowFloor = checkNumber(t.climbingNowFloor)
    self._climbingMaxFloor = checkNumber(t.climbingMaxFloor)
    self._climbingAssembleBuffIds = checkTable(t.climbingAssembleBuffIds)

    if self._isInit then
        local t1 = checkTable(t.climbingHaveBuffIds)
        local t2 = checkTable(self._climbingHaveBuffIds)

        for k, v in pairs(t1) do
            if checkNumber(t2[checkString(k)]) == 0 then
                self._redPointList[checkString(k)] = 1 
            end
        end

        self._climbingHaveBuffIds = checkTable(t.climbingHaveBuffIds)
    else
        if isNull(self._redPointList) then
            self._redPointList = {}
        end

        self._climbingHaveBuffIds = checkTable(t.climbingHaveBuffIds)
        self._isInit = true
    end
    print(table.dump(self._climbingHaveBuffIds))

    self:StartTimeDown()
end

function NightCatQuestComponent:GetClimbingNowFloor()
    return checkNumber(self._climbingNowFloor)
end

--剧情结束单独刷新一次buff
function NightCatQuestComponent:RefreshBuff(jsonData)
    local t = checkTable(jsonData.climbingInfo)

    local t1 = checkTable(t.climbingHaveBuffIds)
    local t2 = checkTable(self._climbingHaveBuffIds)

    for k, v in pairs(t1) do
        if checkNumber(t2[checkString(k)]) == 0 then
            self._redPointList[checkString(k)] = 1 
        end
    end

    self._climbingHaveBuffIds = checkTable(t.climbingHaveBuffIds)
end

--暗夜猫活动首页
function NightCatQuestComponent:ActivityNightCatHomeReq(activityUuid, cb)
    GameUtils.Request(Interfaces.ActivityNightCatHome, {activityUuid = activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._activityUuId = checkNumber(activityUuid)

        local activityConf = checkTable(jsonData.activityConf)
        self._curActivityId = checkNumber(activityConf.id)

        self._climbingResetTtl = checkNumber(jsonData.climbingResetTtl)
        local t = checkTable(jsonData.climbingInfo)
        self._curTowerQuestId = checkNumber(t.climbingNowFloor)
        self._climbingResetNum = checkNumber(t.climbingResetNum)
        self._climbingMaxFloor = checkNumber(t.climbingMaxFloor)
        self._climbingAssembleBuffIds = checkTable(t.climbingAssembleBuffIds)
        self._climbingHaveBuffIds = checkTable(t.climbingHaveBuffIds)
        
        self:StartTimeDown()

        if cb then
            cb()
        end
    end)
end

--开始倒计时
function NightCatQuestComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._climbingResetTtl = checkNumber(self._climbingResetTtl) - 1
    end, CountDownTime, false, true)
end

--暗夜猫活动爬塔重置
function NightCatQuestComponent:ActivityNightCatResetReq(cb)
    GameUtils.Request(Interfaces.ActivityNightCatReset, {activityUuid = self._activityUuId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._curTowerQuestId = 0
        if cb then
            cb(jsonData)
        end
    end)
end

--暗夜猫活动增益升级
function NightCatQuestComponent:ActivityNightCatGainUpReq(goodsId, cb)
    GameUtils.Request(Interfaces.ActivityNightCatGainUp, {activityUuid = self._activityUuId, goodsId = goodsId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        if self._climbingHaveBuffIds[checkString(goodsId)] then
            self._climbingHaveBuffIds[checkString(goodsId)] = checkNumber(jsonData.newLevel)
        end
        local t = QuestConfMgr:GetInstance():GetNightCatBuffUpLevelConsume(goodsId, jsonData.newLevel)
        
        GoodsUtils.DrawRewards({{
            goodsId = t.goodsId,
            num = t.num * -1
        }}, true)

        if cb then
            cb()
        end
    end)
end

--暗夜猫活动增益变更
function NightCatQuestComponent:ActivityNightCatGainChangeReq(goodsId, type, cb)
    type = checkNumber(type)
    GameUtils.Request(Interfaces.ActivityNightCatGainChange, {activityUuid = self._activityUuId, goodsId = goodsId, type = type}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        --[[
        --卸下 
        if type == 1 then
            local ind = table.keyof(self._climbingAssembleBuffIds, checkString(goodsId))
            if checkNumber(ind) > 0 then
                table.remove(self._climbingAssembleBuffIds, ind)
            end
        --装配
        elseif type == 2 then
            table.insert(self._climbingAssembleBuffIds, checkString(goodsId))
        end
        ]]
        self._climbingAssembleBuffIds = checkTable(jsonData.climbingInfo.climbingAssembleBuffIds)
        
        if cb then
            cb()
        end
    end)
end




--buff是否满级
function NightCatQuestComponent:IsBuffMaxLevel(buffId)
    if not self._climbingHaveBuffIds then
        return false
    end

    local maxLevel = QuestConfMgr:GetInstance():GetNightCatBuffMaxLevel(buffId)
    local level = self._climbingHaveBuffIds[checkString(buffId)]

    return checkNumber(level) >= checkNumber(maxLevel)
end

--获取buff等级
function NightCatQuestComponent:GetBuffLevel(buffId)
    if not self._climbingHaveBuffIds then
        return false
    end
    local level = self._climbingHaveBuffIds[checkString(buffId)]
    return checkNumber(level)
end

--是否装备了这个buff
function NightCatQuestComponent:IsEquipBuff(buffId)
    if not self._climbingAssembleBuffIds then
        return false
    end
    local ind = table.keyof(self._climbingAssembleBuffIds, checkNumber(buffId))

    return checkNumber(ind) > 0
end

