    return checkNumber(self._curTowerQuestId)
end

--当前最大通关的爬塔id
function NightCatQuestComponent:GetMaxPassTowerId()
    return checkNumber(self._climbingMaxFloor)
end

--当前最大通关的爬塔id
function NightCatQuestComponent:GetEquipBuffInfo()
