end


--- 当前装备的buff 全部战力加成
---@return integer
function NightCatQuestComponent:GetEquipBuffAddPower()
    local addPower  = 0
    local tableName = string.format("%sIDGroup", AutoIds.IdSetting2731)
    for _, buffId in ipairs(self:GetEquipBuffInfo()) do
        if checkInt(buffId) > 0 then
            local level = self:GetBuffLevel(buffId)
            local effectId = CfUtils.GetStringIdGroupData(tableName, buffId.."_"..level)
            local questUpBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(effectId) or {}
            if questUpBuffVo then
                addPower = addPower + checkInt(questUpBuffVo.combatValue1)
            end
        end
    end
    return addPower
end


