--是否活动中
function NightCatQuestComponent:IsOpen()
    local ActivityNightCatMgr = import('Game.Activity.NightCat.ActivityNightCatMgr')
    local isEnd = ActivityNightCatMgr:GetInstance():CheckActivityEnded(false)
    return not isEnd
end

--是否解锁buff
function NightCatQuestComponent:IsUnlockNightCatBuff(id)
    return checkNumber(self._climbingHaveBuffIds[checkString(id)]) > 0
end

--是否可以重置爬塔
function NightCatQuestComponent:IsCanResetTower()
    return checkNumber(self._climbingResetTtl) <= 0
end

--是否有重置次数
function NightCatQuestComponent:IsHasResetNum(id)
    local vo = QuestConfMgr:GetInstance():GetNightCatActivityVo(id)
    if not vo then
        return false
    end
    local t = CfUtils.Split(vo.resetTime)
    if not t then
        return false
    end

    return (checkNumber(self._climbingResetNum) < table.count(t))
end

---GetLeftResetNum 获取剩余重置次数
---@param id number 活动ID
function NightCatQuestComponent:GetLeftResetNum(id)
    local vo = QuestConfMgr:GetInstance():GetNightCatActivityVo(id)
    if not vo then
        return 0
    end
    local t = CfUtils.Split(vo.resetTime)
    if not t then
        return 0
    end
    return table.count(t) - checkNumber(self._climbingResetNum)
end

