function NightCatQuestComponent:FastClimbingTowerReq(activityId, cb)
    GameUtils.Request(Interfaces.ActivityNightCatFastClimbing, {activityUuid = activityId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = checkTable(response.data)
        if #jsonData.rewards > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })
        end
        if cb then
            cb()
        end
    end)
end

---IsPassLevelById 是否通关关卡
---@param levelId string 关卡id 
function NightCatQuestComponent:IsPassLevelById(levelId)
    return checkNumber(self._curTowerQuestId) >= checkNumber(levelId)
end

return NightCatQuestComponent